public sealed class TVMirrorHost:HwndHost {
 IntPtr surface=IntPtr.Zero,video=IntPtr.Zero;public IntPtr Video{get{return video;}}
 [DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern IntPtr CreateWindowEx(int ex,string cls,string name,int style,int x,int y,int w,int h,IntPtr parent,IntPtr menu,IntPtr inst,IntPtr param);
 [DllImport("user32.dll")]static extern bool DestroyWindow(IntPtr h);
 [DllImport("user32.dll")]static extern IntPtr SetParent(IntPtr child,IntPtr parent);
 [DllImport("user32.dll",EntryPoint="GetWindowLongW")]static extern int GetWindowLong(IntPtr h,int index);
 [DllImport("user32.dll",EntryPoint="SetWindowLongW")]static extern int SetWindowLong(IntPtr h,int index,int value);
 [DllImport("user32.dll")]static extern bool MoveWindow(IntPtr h,int x,int y,int w,int height,bool repaint);
 [DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int cmd);
 [DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint msg,IntPtr w,IntPtr l);
 protected override HandleRef BuildWindowCore(HandleRef parent){surface=CreateWindowEx(0,"STATIC","TV Mirror",unchecked((int)0x50000000),0,0,1,1,parent.Handle,IntPtr.Zero,IntPtr.Zero,IntPtr.Zero);return new HandleRef(this,surface);}
 protected override void DestroyWindowCore(HandleRef hwnd){if(video!=IntPtr.Zero){SetParent(video,IntPtr.Zero);video=IntPtr.Zero;}DestroyWindow(hwnd.Handle);surface=IntPtr.Zero;}
 public void Attach(IntPtr hwnd){if(surface==IntPtr.Zero)throw new Exception("投屏容器尚未就绪");video=hwnd;int style=GetWindowLong(video,-16);style=(style&~unchecked((int)0x80CF0000))|0x40000000;SetWindowLong(video,-16,style);SetParent(video,surface);ResizeVideo();ShowWindow(video,5);}
 public void CloseVideo(){if(video!=IntPtr.Zero)PostMessage(video,0x10,IntPtr.Zero,IntPtr.Zero);}
 public IntPtr ReleaseVideo(){var old=video;if(video!=IntPtr.Zero)SetParent(video,IntPtr.Zero);video=IntPtr.Zero;return old;} public void Forget(){video=IntPtr.Zero;}
 void ResizeVideo(){if(video==IntPtr.Zero)return;var source=PresentationSource.FromVisual(this);double scale=source==null?1:source.CompositionTarget.TransformToDevice.M11;MoveWindow(video,0,0,Math.Max(1,(int)(ActualWidth*scale)),Math.Max(1,(int)(ActualHeight*scale)),true);}
 protected override void OnWindowPositionChanged(Rect rect){base.OnWindowPositionChanged(rect);ResizeVideo();}
}

