 void BuildMirrorPage(){var board=new StackPanel();board.Children.Add(Text("电视工作台",28,"#202431"));board.Children.Add(Text("连接电视后开始投屏，也可以将画面弹出为独立窗口。",13));var bar=new WrapPanel{Margin=new Thickness(0,12,0,12)};castToggle=ActionButton(bar,"▶ 开始投屏",()=>ToggleCast());floatToggle=ActionButton(bar,"独立窗口",()=>ToggleFloating());ActionButton(bar,"截屏",()=>CaptureScreen());recordToggle=ActionButton(bar,"开始录屏",()=>ToggleRecording());ActionButton(bar,"安装 APK",()=>ChooseApks());ActionButton(bar,"文件管理",()=>Show("文件管理"));board.Children.Add(bar);
