 void ChooseApks(){if(busy){Report("当前任务执行中，请结束后导入 APK。");return;}var d=new OpenFileDialog{Filter="Android 安装包|*.apk",Multiselect=true};if(d.ShowDialog()==true)ImportApks(d.FileNames);}
 bool Streaming {get{return mirrorProcess!=null&&!mirrorProcess.HasExited;}}
 void EnsureStreamIdle(){if(Streaming||streamStarting)throw new Exception("请先停止当前投屏或录屏，再切换连接设备。");}
 void UpdateMirrorState(){if(mirrorStatus==null)return;bool live=Streaming;mirrorStatus.Text=live?(recordingFile==""?"● 投屏中 · "+serial:"● 录屏中 · 停止后保存到 "+recordingFile):"● 尚未开启投屏";if(castToggle!=null){castToggle.Content=streamStarting?"连接中…":live?"■ 停止投屏":"▶ 开始投屏";castToggle.IsEnabled=!streamStarting;}if(floatToggle!=null)floatToggle.Content=floatingWindow==null?"独立窗口":"返回工作台";if(recordToggle!=null)recordToggle.Content=live&&recordingFile!=""?"停止录屏":"开始录屏";if(dropTitle!=null){dropTitle.Text=live&&floatingWindow!=null?"投屏已在独立窗口打开":"把 APK 拖拽到这里安装";dropSubtitle.Text=live?"将 APK 拖入电视画面即可安装":"连接电视后可安装 · 开始投屏后，直接拖入电视画面";}if(mirrorHint!=null)mirrorHint.Text=live?"拖拽 APK 到"+(floatingWindow==null?"电视画面":"独立窗口中的电视画面")+"安装；其他文件上传至 Download。":"未投屏时，将 APK 拖到上方区域安装。";}
 string MirrorArguments(string destination){if(serial=="")throw new Exception("请先连接电视");return "--serial="+Q(serial)+" --no-audio --max-size=1920 --max-fps=30 --window-title="+Q("瞎折腾电视投屏")+" --window-borderless --no-window-aspect-ratio-lock --push-target=/sdcard/Download/"+(destination==""?"":" --record="+Q(destination));}
 async Task StartMirror(string destination){if(serial=="")throw new Exception("请先连接电视");if(Streaming){if(destination==""&&recordingFile==""){Show("投屏工作台");return;}await StopMirror();}Show("投屏工作台");streamStarting=true;UpdateMirrorState();mirrorStatus.Text="● 正在建立电视视频连接…";try{await Adb("start-server",false);mirrorHost.Visibility=Visibility.Visible;tvPlaceholder.Visibility=Visibility.Collapsed;mirrorPage.UpdateLayout();var info=new ProcessStartInfo(Root+"mirror/scrcpy.exe",MirrorArguments(destination)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8,WorkingDirectory=Root+"mirror"};info.EnvironmentVariables["ADB"]=Root+"adb.exe";info.EnvironmentVariables["ADB_SERVER_SOCKET"]="tcp:127.0.0.1:15037";info.EnvironmentVariables["ANDROID_ADB_SERVER_PORT"]="15037";info.EnvironmentVariables["SCRCPY_SERVER_PATH"]=Root+"mirror/scrcpy-server";
 var p=new Process{StartInfo=info,EnableRaisingEvents=true};p.OutputDataReceived+=(s,e)=>StreamLog(e.Data);p.ErrorDataReceived+=(s,e)=>StreamLog(e.Data);mirrorProcess=p;recordingFile=destination;p.Start();p.BeginOutputReadLine();p.BeginErrorReadLine();p.Exited+=(s,e)=>Dispatcher.BeginInvoke(new Action(()=>{if(mirrorProcess!=p)return;ActiveHost.Forget();CloseFloating();mirrorHost.Forget();mirrorHost.Visibility=Visibility.Collapsed;tvPlaceholder.Visibility=Visibility.Visible;string f=recordingFile;recordingFile="";mirrorProcess=null;UpdateMirrorState();Report("投屏已退出。"+(f==""?"":"录屏文件："+f+"，请检查是否完整。"));}));
 for(int i=0;i<100;i++){if(p.HasExited)throw new Exception("电视投屏进程退出，请查看运行记录（设备可能不支持视频编码 / 调试未授权）。");p.Refresh();if(p.MainWindowHandle!=IntPtr.Zero){mirrorHost.Attach(p.MainWindowHandle);if(preferFloating)await FloatMirror();UpdateMirrorState();return;}await Task.Delay(120);}p.CloseMainWindow();throw new Exception("投屏窗口建立超时，已请求关闭本次投屏；请查看日志。");
 }catch{mirrorHost.Visibility=Visibility.Collapsed;tvPlaceholder.Visibility=Visibility.Visible;throw;}finally{streamStarting=false;UpdateMirrorState();}}
 void StreamLog(string s){if(string.IsNullOrWhiteSpace(s))return;Dispatcher.BeginInvoke(new Action(()=>Report("投屏："+s)));}
 async Task StopMirror(){var p=mirrorProcess;if(p==null)return;string destination=recordingFile;if(!p.HasExited){if(ActiveHost.Video!=IntPtr.Zero)ActiveHost.CloseVideo();else p.CloseMainWindow();bool done=await Task.Run(()=>p.WaitForExit(10000));if(!done)throw new Exception("投屏仍未退出。为避免损坏录屏文件，没有强杀，请稍后重试停止。");}if(mirrorProcess==p){mirrorProcess=null;recordingFile="";ActiveHost.Forget();CloseFloating();mirrorHost.Forget();mirrorHost.Visibility=Visibility.Collapsed;tvPlaceholder.Visibility=Visibility.Visible;}UpdateMirrorState();if(destination!="")Report(File.Exists(destination)&&new FileInfo(destination).Length>0?"录屏已停止并写入："+destination:"录屏文件未生成，请检查投屏日志。");p.Dispose();}
 void ToggleRecording(){if(busy){Report("请等待当前任务结束。");return;}if(Streaming&&recordingFile!=""){Run(async()=>await StopMirror());return;}if(serial=="")throw new Exception("请先连接电视");var d=new SaveFileDialog{Filter="Matroska 视频（无声音）|*.mkv",FileName="电视录屏-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".mkv"};if(d.ShowDialog()==true)Run(async()=>await StartMirror(d.FileName));}
 void CaptureScreen(){if(serial=="")throw new Exception("请先连接电视");var d=new SaveFileDialog{Filter="PNG 截图|*.png",FileName="电视截图-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".png"};if(d.ShowDialog()!=true)return;Run(async()=>{await CapturePng(d.FileName);Report("截图已保存："+d.FileName);});}
 async Task CapturePng(string destination){string temporary=destination+".partial-"+Guid.NewGuid().ToString("N");try{var info=new ProcessStartInfo(Root+"adb.exe","-P 15037 -s "+Q(serial)+" exec-out screencap -p"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(info)){var errors=p.StandardError.ReadToEndAsync();using(var output=File.Create(temporary)){var copy=p.StandardOutput.BaseStream.CopyToAsync(output);var timeout=Task.Delay(30000);if(await Task.WhenAny(copy,timeout)!=copy){p.Kill();throw new Exception("截屏超时");}await copy;}bool exited=await Task.Run(()=>p.WaitForExit(5000));if(!exited){p.Kill();throw new Exception("截屏命令未退出");}if(p.ExitCode!=0)throw new Exception(await errors);}byte[] header=new byte[8];using(var f=File.OpenRead(temporary))if(f.Read(header,0,8)!=8)throw new Exception("截屏数据不完整");byte[] expected={137,80,78,71,13,10,26,10};if(!header.SequenceEqual(expected))throw new Exception("设备未返回 PNG，可能不支持截屏或处于受保护画面");File.Copy(temporary,destination,true);}finally{if(File.Exists(temporary))File.Delete(temporary);}}
 async void StudioClosing(object sender,System.ComponentModel.CancelEventArgs e){if(closingStudio)return;if(busy){e.Cancel=true;Report("操作尚未结束，请等待后退出或升级。");return;}if(Streaming){e.Cancel=true;try{await StopMirror();closingStudio=true;Close();}catch(Exception ex){Report(ex.Message);}}}
